 15	\subsection{Finite fields}
 16	
 17	A \emph{finite field} is a field with a finite number of elements.
 18	There is a unique finite field~$\F_q$ of~$q$ elements for each prime power $q = p^t$,
 19	and there are no other finite fields.
 20	We write $\omega$ for the $p$-th root of unity $\omega = e^{2 \pi i/p}$.
 21	
 22	\begin{definition}[Finite field trace]
 23	The \emph{finite field trace} is the function $\tr:\F_q \rightarrow \F_p$ defined as
 24	\begin{equation*}
 25	\tr[x] = \sum_{\ell=0}^{t-1} x^{p^{\ell}}.
 26	\end{equation*}
 27	\end{definition}
 28	
 29	\begin{proposition}
 30	\label{prop:fourier-fact-scalar}
 31	Let $a \in \F_q$. Then
 32	\begin{equation*}
 33	\E_{\bx \sim \F_q} \omega^{\tr[\bx \cdot a]}
 34	= \left\{\begin{array}{rl}
 35		1 & \text{if $a = 0$},\\
 36		0 & \text{otherwise}.
 37		\end{array}\right.
 38	\end{equation*}
 39	\end{proposition}
 40	\begin{proof}
 41	If $a = 0$, then $\tr[x \cdot a] = 0$ for all $x \in \F_q$.
 42	As a result,
 43	\begin{equation*}
 44	\E_{\bx \sim \F_q} \omega^{\tr[\bx \cdot a]}
 45	= \E_{\bx \sim \F_q} \omega^{0}
 46	= \E_{\bx \sim \F_q} 1
 47	= 1.
 48	\end{equation*}
 49	On the other hand, if $a \neq 0$, then there exists a $y \in \F_q$
 50	such that $\tr[a \cdot y] \neq 0$. As a result,
 51	\begin{equation*}
 52	C
 53	:= \E_{\bx \sim \F_q} \omega^{\tr[\bx \cdot a]}
 54	= \E_{\bx \sim \F_q} \omega^{\tr[(\bx+y) \cdot a]}
 55	= \E_{\bx \sim \F_q} (\omega^{\tr[\bx \cdot a]} \cdot \omega^{\tr[y \cdot a]})
 56	= C \cdot \omega^{\tr[y\cdot a]}.
 57	\end{equation*}
 58	But because $\tr[y \cdot a] \neq 0$,
 59	$\omega^{\tr[y\cdot a]} \neq 1$.
 60	This implies that $C = 0$.
 61	\end{proof}
 62	
 63	
 64	\begin{proposition}
 65	\label{prop:fourier-fact-vector}
 66	Let $v \in \F_q^m$. Then
 67	\begin{equation*}
 68	\E_{\bu \sim \F_q^m} \omega^{\tr[\bu \cdot v]}
 69	= \left\{\begin{array}{rl}
 70		1 & \text{if $v = 0$},\\
 71		0 & \text{otherwise}.
 72		\end{array}\right.
 73	\end{equation*}
 74	\end{proposition}
 75	\begin{proof}
 76	By the linearity of the trace,
 77	\begin{equation*}
 78	\E_{\bu \sim \F_q^m} \omega^{\tr[\bu \cdot v]}
 79	= \E_{\bu \sim \F_q^m} (\omega^{\tr[\bu_1 \cdot v_1]} \cdots \omega^{\tr[\bu_m \cdot v_m]})
 80	= \prod_{i=1}^m (\omega^{\tr[\bu_i \cdot v_i]}),
 81	\end{equation*}
 82	which by \Cref{prop:fourier-fact-scalar} is $1$ if $v_i = 0$ for all $i$ and $0$ otherwise.
 83	\end{proof}
